    private static readonly double[] Crossovers={200,500,1200,3000,7000};
    private static bool Cancelled(RefCounted? job)=>job!=null&&job.Call("is_cancelled").AsBool();
    private static double Value(Settings data,string key,double fallback)=>data.TryGetValue(key,out var value)?value.AsDouble():fallback;
    private static Settings Failure(string text)=>new() {["success"]=false,["error"]=text};
    public Settings process_f32(string inputPath,string outputPath,Settings effect,int rate,RefCounted? job)
    {
        if(ProjectSettings.GlobalizePath(inputPath).SimplifyPath()==ProjectSettings.GlobalizePath(outputPath).SimplifyPath()||Godot.FileAccess.FileExists(outputPath))return Failure("Restoration requires a new temporary output.");using var file=Godot.FileAccess.Open(inputPath,Godot.FileAccess.ModeFlags.Read);if(file==null||file.GetLength()>64*1024*1024||file.GetLength()%8!=0)return Failure("Decay suppression supports stereo float stages up to 64 MiB. Split/bake a shorter region.");if(effect.TryGetValue("automation",out var automation))foreach(var curve in automation.AsGodotDictionary().Values)if(curve.AsGodotArray().Count>0)return Failure("Decay suppression currently uses static controls; remove its parameter automation.");long frames=(long)file.GetLength()/8;using var output=Godot.FileAccess.Open(outputPath,Godot.FileAccess.ModeFlags.Write);if(output==null)return Failure("Could not open the restoration output.");var p=effect.TryGetValue("parameters",out var parameters)?parameters.AsGodotDictionary():new Settings();double strength=Math.Clamp(Value(p,"strength",.6),0,1),decay=Math.Clamp(Value(p,"decay",.6),.05,2),floorGain=Mathf.DbToLinear(Math.Clamp(Value(p,"floor",-12),-30,0));var states=new Vector2[5];var peaks=new double[6];var gains=new double[6];Array.Fill(gains,1);var alphas=new double[5];for(int band=0;band<5;band++)alphas[band]=1-Math.Exp(-Math.Tau*Math.Min(Crossovers[band],rate*.4)/rate);long cursor=0;ulong started=Time.GetTicksMsec();string error="";
        while(cursor<frames){if(Time.GetTicksMsec()-started>60000){error="Decay suppression exceeded its 60-second processing budget. Split a shorter region.";break;}if(Cancelled(job)){error="Cancelled.";break;}int count=(int)Math.Min(256,frames-cursor);var bytes=file.GetBuffer(count*8);if(bytes.Length!=count*8){error="The staged audio ended unexpectedly.";break;}var bands=new Vector2[6][];var energy=new double[6];for(int band=0;band<6;band++)bands[band]=new Vector2[count];for(int index=0;index<count;index++){var value=new Vector2(BitConverter.Int32BitsToSingle(BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(index*8,4))),BitConverter.Int32BitsToSingle(BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(index*8+4,4))));if(!value.IsFinite()){error="Non-finite staged restoration audio.";break;}var previous=Vector2.Zero;for(int band=0;band<5;band++){states[band]=states[band].Lerp(value,(float)alphas[band]);var component=states[band]-previous;previous=states[band];bands[band][index]=component;energy[band]+=component.LengthSquared()*.5;}bands[5][index]=value-previous;energy[5]+=(value-previous).LengthSquared()*.5;}if(error.Length>0)break;var targets=new double[6];for(int band=0;band<6;band++){double rms=Math.Sqrt(energy[band]/count);peaks[band]=Math.Max(rms,peaks[band]*Math.Exp(-6.907755*count/rate/decay));double fall=Math.Clamp((1-rms/Math.Max(.00000001,peaks[band]))/.65,0,1);targets[band]=Math.Max(floorGain,1-strength*fall);}for(int index=0;index<count;index++){var value=Vector2.Zero;for(int band=0;band<6;band++)value+=bands[band][index]*(float)Mathf.Lerp(gains[band],targets[band],(double)(index+1)/count);BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(index*8,4),BitConverter.SingleToInt32Bits(value.X));BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(index*8+4,4),BitConverter.SingleToInt32Bits(value.Y));}gains=targets;output.StoreBuffer(bytes);if(output.GetError()!=Error.Ok){error="Could not write the restoration output.";break;}cursor+=count;job?.Call("update",(double)cursor/Math.Max(1,frames),"Suppressing diffuse decay (multiband)");}file.Close();output.Close();if(error.Length>0){DirAccess.RemoveAbsolute(outputPath);return Failure(error);}return new Settings {["success"]=true,["error"]="",["duration"]=(double)frames/rate};
    }
    public Settings breath_candidates(Variant source,double start,double duration,RefCounted? job)
    {
        if(duration<=0||duration>60)return new Settings {["error"]="Breath review supports a source window up to 60 seconds; split a shorter dialogue clip."};var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",source,Variant.From(job)).As<AudioStream>();if(stream==null)return new Settings {["error"]="The dialogue source is unavailable."};using var cache=new AudioSourceCacheOperations();var decoded=cache.decode(stream,24000,start,duration,60);if(decoded.TryGetValue("error",out var error)&&error.AsString().Length>0)return decoded;var samples=decoded["samples"].AsVector2Array();const int hop=480;var regions=new GArray();int first=-1;for(int frame=0;frame<samples.Length;frame+=hop){if(Cancelled(job))return new Settings {["error"]="Cancelled."};int end=Math.Min(samples.Length,frame+hop),crossings=0;double power=0,peak=0,previous=0;for(int index=frame;index<end;index++){double value=((double)samples[index].X+samples[index].Y)*.5;power+=value*value;peak=Math.Max(peak,Math.Abs(value));if(value*previous<0)crossings++;previous=value;}double rms=Math.Sqrt(power/Math.Max(1,end-frame)),db=Mathf.LinearToDb(Math.Max(.000001,rms));bool candidate=db> -55&&db< -16&&(double)crossings/Math.Max(1,end-frame)>.12&&peak/Math.Max(.000001,rms)<5;if(candidate&&first<0)first=frame;if(first>=0&&(!candidate||end==samples.Length)){int last=!candidate?frame:end;double seconds=(double)(last-first)/24000;if(seconds>=.05&&seconds<=.8)regions.Add(new Settings {["start"]=start+(double)first/24000,["end"]=start+(double)last/24000});first=-1;}}return new Settings {["error"]="",["regions"]=regions};
    }
}
